widget.solution:
class Trade:
    def __init__(self, ticker: str, qty: int, price: float) -> None:
        self.ticker = ticker
        self.qty = qty
        self.price = price


class Book:
    def __init__(self) -> None:
        self.trades = []

    def add(self, trade: Trade) -> None:
        self.trades.append(trade)

    def net(self, ticker: str) -> int:
        total = 0
        for t in self.trades:
            if t.ticker == ticker:
                total += t.qty
        return total

    def cash(self) -> float:
        paid = 0.0
        for t in self.trades:
            paid += t.qty * t.price
        return round(-paid, 2)

